export declare const customDefaultTheme = "/* \u9ED8\u8BA4\u4E3B\u9898 \u00B7 \u7FE1\u7FE0\u520A\u8BFB\n * \u8BBE\u8BA1\u8BED\u8A00\uFF1A\u6DF1\u677E\u58A8\u627F\u62C5\u6807\u9898\u5C42\u7EA7\uFF08\u8FD1\u9ED1\u800C\u6709\u7EFF\u9B42\uFF09\uFF0C\u7FE1\u7FE0 #047857 \u4F5C\u5355\u4E00\u951A\u70B9\u5F3A\u8C03\uFF0C\n * \u6BCF\u7EA7\u6807\u9898\u4F7F\u7528\u4E0D\u540C\u7248\u5F0F\uFF08\u520A\u5934\u538B\u7EBF / \u7AE0\u8282\u5E95\u7EBF / \u7FE1\u7FE0\u5DE6\u951A / \u5B57\u8DDD\u6807\u7B7E\uFF09\u5EFA\u7ACB\u7F16\u8F91\u8282\u594F\uFF1B\n * \u5168\u7A0B\u4E0D\u7528\u6295\u5F71\u3001\u5916\u53D1\u5149\u3001\u6E10\u53D8\u6216\u4F2A\u5143\u7D20\u88C5\u9970\uFF0C\u4FDD\u8BC1\u590D\u5236\u5230\u5FAE\u4FE1\u516C\u4F17\u53F7\u540E\u89C6\u89C9\u7A33\u5B9A\u3002\n * \u6240\u6709\u989C\u8272\u4E3A\u5B57\u9762\u503C\u3002\n */\n\n/* \u5168\u5C40 */\n#wemd {\n  font-family: -apple-system, BlinkMacSystemFont, \"Segoe UI\", \"PingFang SC\", \"Hiragino Sans GB\", \"Microsoft YaHei\", sans-serif;\n  color: #242a26;\n  line-height: 1.8;\n  font-size: 16px;\n  letter-spacing: 0.4px;\n}\n\n/* \u6BB5\u843D */\n#wemd p {\n  margin: 16px 0;\n  font-size: 16px;\n  color: #242a26;\n  line-height: 1.8;\n  letter-spacing: 0.4px;\n}\n\n/* \u4E00\u7EA7\u6807\u9898 \u00B7 \u520A\u5934\uFF1A\u7FE1\u7FE0\u538B\u9876\u7EBF + \u5DE6\u5BF9\u9F50\u5927\u5B57\u58A8\u9898 */\n#wemd h1 {\n  font-size: 30px;\n  font-weight: 800;\n  color: #12241c;\n  text-align: left;\n  margin: 10px 0 28px;\n  padding-top: 18px;\n  border-top: 3px solid #047857;\n  line-height: 1.35;\n  letter-spacing: -0.3px;\n}\n\n/* \u4E8C\u7EA7\u6807\u9898 \u00B7 \u7AE0\u8282\uFF1A\u6DF1\u677E\u58A8 + \u7FE1\u7FE0\u5E95\u7EBF\uFF0C\u5F62\u6210\u680F\u76EE\u5206\u8282 */\n#wemd h2 {\n  font-size: 22px;\n  font-weight: 700;\n  color: #134034;\n  margin: 42px 0 16px;\n  padding-bottom: 10px;\n  border-bottom: 2px solid #cfe4d9;\n  line-height: 1.45;\n  letter-spacing: 0.2px;\n}\n\n/* \u4E09\u7EA7\u6807\u9898 \u00B7 \u7FE1\u7FE0\u5DE6\u951A */\n#wemd h3 {\n  font-size: 18px;\n  font-weight: 600;\n  color: #134034;\n  margin: 30px 0 12px;\n  padding-left: 12px;\n  border-left: 3px solid #047857;\n  line-height: 1.5;\n  letter-spacing: 0.2px;\n}\n\n/* \u56DB\u7EA7\u6807\u9898 \u00B7 \u7FE1\u7FE0\u5B57\u8DDD\u6807\u7B7E */\n#wemd h4 {\n  font-size: 14px;\n  font-weight: 700;\n  color: #047857;\n  margin: 26px 0 10px;\n  letter-spacing: 1px;\n  text-transform: uppercase;\n}\n\n/* \u4E94\u7EA7\u6807\u9898 */\n#wemd h5 {\n  font-size: 15px;\n  font-weight: 600;\n  color: #55605a;\n  margin: 20px 0 8px;\n  letter-spacing: 0.3px;\n}\n\n/* \u516D\u7EA7\u6807\u9898:\u6700\u6B21\u7EA7\u58A8\u7070,\u538B\u6DF1\u81F3\u5BF9\u767D\u5E95 \u2265 AA 4.5:1 */\n#wemd h6 {\n  font-size: 14px;\n  font-weight: 600;\n  color: #606b64;\n  margin: 18px 0 8px;\n  letter-spacing: 0.5px;\n}\n\n/* \u65E0\u5E8F\u5217\u8868\uFF1A\u7FE1\u7FE0\u7B26\u53F7 + \u58A8\u8272\u5185\u5BB9 */\n#wemd ul {\n  padding-left: 24px;\n  list-style-type: disc;\n  color: #242a26;\n}\n\n#wemd ul li {\n  padding-left: 6px;\n  color: #047857;\n}\n\n#wemd ul li section {\n  color: #242a26;\n}\n\n#wemd ul ul {\n  list-style-type: circle;\n}\n\n#wemd ul ul ul {\n  list-style-type: square;\n}\n\n/* \u6709\u5E8F\u5217\u8868 */\n#wemd ol {\n  padding-left: 24px;\n  list-style-type: decimal;\n  color: #242a26;\n}\n\n#wemd ol li {\n  padding-left: 6px;\n  color: #047857;\n}\n\n#wemd li section {\n  margin: 7px 0;\n  line-height: 1.8;\n  font-size: 16px;\n  color: #242a26;\n}\n\n/* \u4E00\u7EA7\u5F15\u7528\uFF1A\u7FE1\u7FE0\u5DE6\u951A + \u6781\u6D45\u7FE1\u7FE0\u5E95\uFF0C\u53F3\u4FA7\u5706\u89D2 */\n#wemd .multiquote-1 {\n  border-left: 3px solid #047857;\n  background: #f0f6f3;\n  padding: 16px 20px;\n  margin: 24px 0;\n  color: #3f4a44;\n  border-radius: 0 8px 8px 0;\n  box-shadow: none;\n}\n\n#wemd .multiquote-1 p {\n  margin: 0;\n  font-size: 15.5px;\n  color: #3f4a44;\n  line-height: 1.8;\n}\n\n/* \u4E8C\u7EA7\u5F15\u7528\uFF08\u8986\u76D6 basic \u7684\u6295\u5F71\uFF09 */\n#wemd .multiquote-2 {\n  border-left: 3px solid #065f46;\n  background: #f6f8f7;\n  padding: 14px 18px;\n  margin: 18px 0;\n  border-radius: 0 8px 8px 0;\n  box-shadow: none;\n}\n\n#wemd .multiquote-2 p {\n  margin: 0;\n  font-size: 15px;\n  color: #55605a;\n  line-height: 1.75;\n}\n\n/* \u4E09\u7EA7\u5F15\u7528\uFF08\u8986\u76D6 basic \u7684\u6295\u5F71\uFF09 */\n#wemd .multiquote-3 {\n  border-left: 2px solid #86c9ae;\n  background: #f6f8f7;\n  padding: 12px 16px;\n  margin: 14px 0;\n  border-radius: 0 8px 8px 0;\n  box-shadow: none;\n}\n\n#wemd .multiquote-3 p {\n  margin: 0;\n  font-size: 14px;\n  color: #55605a;\n}\n\n/* \u94FE\u63A5\uFF1A\u7FE1\u7FE0 + \u7EC6\u4E0B\u5212\u7EBF */\n#wemd a {\n  color: #047857;\n  text-decoration: none;\n  border-bottom: 1px solid rgba(4, 120, 87, 0.4);\n  font-weight: 500;\n}\n\n/* \u52A0\u7C97\uFF1A\u58A8\u8272\u5F3A\u8C03\uFF0C\u4E0D\u67D3\u8272 */\n#wemd strong {\n  font-weight: 700;\n  color: #12241c;\n  letter-spacing: 0.2px;\n}\n\n/* \u659C\u4F53\uFF1A\u58A8\u8272 */\n#wemd em {\n  font-style: italic;\n  color: #242a26;\n}\n\n/* \u52A0\u7C97\u659C\u4F53 */\n#wemd em strong {\n  font-weight: 700;\n  font-style: italic;\n  color: #12241c;\n}\n\n/* \u5220\u9664\u7EBF */\n#wemd del {\n  text-decoration: line-through;\n  color: #606b64;\n}\n\n/* \u5206\u9694\u7EBF \u00B7 \u5C45\u4E2D\u77ED\u7FE1\u7FE0\u6761 */\n#wemd hr {\n  border: none;\n  height: 2px;\n  width: 48px;\n  background: #047857;\n  margin: 34px auto;\n}\n\n/* \u56FE\u7247 */\n#wemd img {\n  display: block;\n  margin: 24px auto;\n  max-width: 100%;\n  border-radius: 6px;\n}\n\n/* \u56FE\u7247\u63CF\u8FF0 */\n#wemd figcaption {\n  text-align: center;\n  font-size: 14px;\n  color: #606b64;\n  margin-top: 10px;\n  letter-spacing: 0.2px;\n}\n\n/* \u94FE\u63A5\u56FE\u7247\u8BF4\u660E\uFF1A\u8986\u76D6\u57FA\u7840\u4E3B\u9898\u7684\u9ED1\u5E95\u60AC\u6D6E\u6837\u5F0F */\n#wemd figure a + figcaption {\n  margin-top: 10px;\n  background: transparent;\n  color: #606b64;\n  line-height: 1.6;\n}\n\n/* \u884C\u5185\u4EE3\u7801\uFF1A\u6D45\u7FE1\u7FE0\u5E95 + \u7FE1\u7FE0\u58A8\u5B57 */\n#wemd p code, #wemd li code, #wemd td code, #wemd th code {\n  background: #eef6f1;\n  padding: 2px 6px;\n  border-radius: 4px;\n  color: #0f5c43;\n  font-family: \"SF Mono\", Monaco, \"Cascadia Code\", \"Roboto Mono\", Consolas, monospace;\n  font-size: 0.88em;\n  margin: 0 2px;\n  border: 1px solid #d4e8de;\n}\n\n/* \u4EE3\u7801\u5757\u5BB9\u5668\uFF1A\u4E2D\u6027\u53D1\u4E1D\u8FB9 */\n#wemd pre code,\n#wemd pre code.hljs {\n  display: block;\n  background: #f7f9f8;\n  padding: 18px;\n  border-radius: 8px;\n  overflow-x: auto;\n  font-family: \"SF Mono\", Monaco, \"Cascadia Code\", \"Roboto Mono\", Consolas, monospace;\n  font-size: 13.5px;\n  line-height: 1.7;\n  color: #334155;\n  border: 1px solid #e4e9e6;\n}\n\n/* \u8868\u683C \u00B7 \u7F16\u8F91\u5F0F\uFF1A\u53BB\u7AD6\u7EBF\uFF0C\u4EC5\u6A2A\u5411\u5206\u9694\uFF0C\u8868\u5934\u7FE1\u7FE0\u5E95\u7EBF */\n#wemd table tr {\n  border: none;\n  background-color: transparent;\n}\n\n#wemd table tr th,\n#wemd table tr td {\n  border: none;\n  border-bottom: 1px solid #e4e9e6;\n  padding: 11px 14px;\n  font-size: 15px;\n  color: #242a26;\n  line-height: 1.6;\n  text-align: left;\n}\n\n#wemd table tr th {\n  border-bottom: 2px solid #047857;\n  background: transparent;\n  color: #134034;\n  font-weight: 700;\n  letter-spacing: 0.3px;\n}\n\n#wemd table tr:nth-child(2n) {\n  background-color: transparent;\n}\n\n#wemd table tr th:nth-of-type(n),\n#wemd table tr td:nth-of-type(n){\n  min-width: 100px;\n}\n\n/* \u811A\u6CE8 */\n#wemd .footnote-word {\n  color: #047857;\n  font-weight: 500;\n  border-bottom: 1px dashed rgba(4, 120, 87, 0.5);\n}\n\n#wemd .footnote-ref {\n  color: #047857;\n  font-weight: 600;\n}\n\n#wemd .footnotes-sep:before {\n  content: \"\u53C2\u8003\u8D44\u6599\";\n  font-weight: 700;\n  margin-top: 38px;\n  margin-bottom: 16px;\n  display: block;\n  font-size: 18px;\n  color: #12241c;\n  letter-spacing: 0.5px;\n}\n\n#wemd .footnote-num {\n  display: inline-block;\n  width: 24px;\n  text-align: right;\n  margin-right: 8px;\n  color: #606b64;\n  font-weight: 500;\n}\n\n#wemd .footnote-item p {\n  display: inline;\n  font-size: 14px;\n  color: #55605a;\n  line-height: 1.8;\n}\n\n#wemd .footnote-item p em {\n  font-style: normal;\n  color: #606b64;\n  margin-left: 6px;\n}\n\n/* \u884C\u95F4\u516C\u5F0F */\n#wemd .block-equation > svg {\n  display: block;\n  margin: 20px auto;\n  max-width: 300% !important;\n}\n\n/* \u884C\u5185\u516C\u5F0F */\n#wemd .inline-equation > svg {\n  vertical-align: middle;\n}\n\n/* Callout \u63D0\u793A\u5757\uFF1A\u6241\u5E73\u5316\uFF0C\u53BB\u6295\u5F71\u6E10\u53D8\uFF1B\u8BED\u4E49\u8272\u5DE6\u8FB9\u7EBF\u7531 basic \u63D0\u4F9B */\n#wemd .callout {\n  margin: 26px 0;\n  padding: 18px 20px;\n  border-radius: 12px;\n  box-shadow: none;\n}\n\n#wemd .callout-title {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  font-weight: 700;\n  margin-bottom: 10px;\n  color: #12241c;\n  font-size: 16px;\n  letter-spacing: 0.03em;\n}\n\n#wemd .callout-icon {\n  margin-right: 8px;\n  font-size: 18px;\n}\n\n/* \u63D0\u793A\u7C7B callout \u4E0E\u4E3B\u9898\u5F3A\u8C03\u8272\u5BF9\u9F50\uFF0C\u5176\u4F59\u4FDD\u6301\u8BED\u4E49\u8272 */\n#wemd .callout-tip {\n  border-left-color: #047857;\n  background: #ecf6f1;\n}\n\n/* \u9AD8\u4EAE\u6587\u672C\uFF1A\u67D4\u548C\u6241\u5E73 */\n#wemd mark {\n  background: #f6eec6;\n  color: #1a1a1a;\n  padding: 2px 5px;\n  border-radius: 3px;\n  font-weight: 500;\n}\n\n/* \u4E0A\u6807 */\n#wemd sup {\n  font-size: 0.75em;\n  vertical-align: super;\n  color: #047857;\n}\n\n/* \u4E0B\u6807 */\n#wemd sub {\n  font-size: 0.75em;\n  vertical-align: sub;\n  color: #047857;\n}\n\n/* Imageflow */\n#wemd .imageflow-layer1 {\n  margin-top: 1em;\n  margin-bottom: 0.5em;\n  border: 0px none;\n  padding: 0px;\n  overflow: hidden;\n}\n\n#wemd .imageflow-layer2 {\n  white-space: nowrap;\n  width: 100%;\n  overflow-x: scroll;\n}\n\n#wemd .imageflow-layer3 {\n  display: inline-block;\n  word-wrap: break-word;\n  white-space: normal;\n  vertical-align: top;\n  width: 80%;\n  margin-right: 10px;\n  flex-shrink: 0;\n}\n\n#wemd .imageflow-img {\n  display: block;\n  width: 100%;\n  height: auto;\n  max-height: 300px;\n  object-fit: contain;\n  border-radius: 4px;\n}\n\n#wemd .imageflow-caption {\n  text-align: center;\n  margin-top: 0px;\n  padding-top: 0px;\n  color: #888;\n}\n";
